export const BRAND = {
  name: "Night Desk",
  description: "Investment intelligence for a nine-stage deal book, on the box.",
  desk: "#1e2a3a",
  copper: "#f0b27a",
  paper: "#f4f7fb",
  memo: "#fff8ee",
  mute: "#b4c0ce",
} as const;

export const LAMP = {
  shade: "M5.2 10.8C5.2 5.55 8 2.75 12 2.75s6.8 2.8 6.8 8.05H5.2Z",
  base: "M8.15 18.55h7.7c.55 0 .88.42.68.85H7.47c-.2-.43.13-.85.68-.85Z",
} as const;

import { LAMP } from "@/lib/brand";

type Props = {
  size?: number;
  className?: string;
};

export function BrandMark({ size = 22, className }: Props) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      className={className}
      aria-hidden="true"
    >
      <path d={LAMP.shade} fill="currentColor" />
      <rect x="11.2" y="10.8" width="1.6" height="6.85" rx="0.8" fill="currentColor" />
      <path d={LAMP.base} fill="currentColor" />
      <rect x="4.6" y="21.45" width="14.8" height="1.15" rx="0.58" fill="currentColor" opacity="0.45" />
    </svg>
  );
}

import Link from "next/link";
import { BRAND } from "@/lib/brand";
import { BrandMark } from "./BrandMark";

type Props = {
  href?: string;
  compact?: boolean;
  size?: number;
};

export function BrandLogo({ href = "/", compact = false, size = 22 }: Props) {
  if (compact) {
    return (
      <Link href={href} aria-label={BRAND.name} className="brand-logo is-compact">
        <BrandMark size={size} />
      </Link>
    );
  }

  return (
    <Link href={href} className="brand-logo">
      <BrandMark size={size} />
      <span className="brand-wordmark">{BRAND.name}</span>
    </Link>
  );
}

import { ImageResponse } from "next/og";
